; VEGETA module: Joch's trial in the Hyperbolic Time Chamber.
; Port of engine/joch-trial.js, engine/time-chamber.js, engine/vegeta-sprite.js,
; engine/vegeta-clash.js and engine/beam-detonation.js (the cues of
; engine/vegeta-arrangement.js belong to the audio module).
; See docs/agents/snes-port/vegeta.md.
;
; Resources:
;   code  !CODE_VEGETA ($A8:8000-FFFF)
;   data  !DATA_VEGETA ($E8:0000-7FFF): chamber metatiles, grid, palettes;
;         generated by snes/gen/vegeta.mjs into dist/snes/gen/vegeta/
;   art   $F4:0000-7FFF (chamber BG tiles, Vegeta OBJ tiles), $F5:0000-7FFF
;   WRAM  !RAM_VEGETA ($7E:DBC0, $40 bytes)
;   SRAM  !SRAM_WORK_SCENE ($32:6000-7FFF) while the trial runs

incsrc "vegeta/chamber_gen.asm"

; ---------------------------------------------------------------------------
; Generated data
pushpc
org !DATA_VEGETA
vegeta_chamber_meta:
incbin "vegeta/chamber_meta.bin"
vegeta_chamber_pal:
incbin "vegeta/chamber_pal.bin"
vegeta_chamber_grid:
incbin "vegeta/chamber_grid.bin"
vegeta_data_end:
assert vegeta_data_end <= !DATA_VEGETA+$8000, "vegeta data bank overflow"
org $F40000
vegeta_chamber_tiles:
incbin "vegeta/chamber_tiles.bin"
vegeta_art_end:
assert vegeta_art_end <= $F48000, "vegeta art exceeds $F4:0000-7FFF"
pullpc

; ---------------------------------------------------------------------------
; Code
pushpc
org !CODE_VEGETA
vegeta_code_start:
incsrc "chamber.asm"
vegeta_code_end:
assert vegeta_code_end <= !CODE_VEGETA+$8000, "vegeta code bank overflow"
pullpc
